from collections import defaultdict

def solve(data):
    n = data['n']
    edges = data['edges']

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Topological sort using Kahn's algorithm
    indegree = [0] * n
    queue = []
    topo_order = []

    # Calculate in-degree of each vertex
    for u in range(n):
        for v in graph[u]:
            indegree[v] += 1

    # Add vertices with zero in-degree to the queue
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    # Perform topological sorting
    while queue:
        u = queue.pop(0)
        topo_order.append(u)

        # Decrease in-degree of adjacent vertices
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    # If there is a cycle, return []
    if len(topo_order) != n:
        return []

    return topo_order

