from collections import defaultdict

def solve(data):
    n = data['n']
    edges = data['edges']

    # Create an adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    # Topological sort using Kahn's algorithm
    indegree = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            indegree[v] += 1

    queue = []
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in adj_list[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return []

